for f in carve-tonight carve-wall1 carve-auto200p; do L=/mnt/e/DSH-Fuxi/logs/$f/lscan.txt; printf '%-16s accepted=%s newArchive=%s renderSession=%s\n' $f "$(grep -a -c 'Accepted successfully to file:.*com.apple.chrono/timelines' $L)" "$(grep -a -c 'timelineAdvancedOrNewArchive' $L)" "$(grep -a -c '<WidgetRenderSession' $L)"; done
grep -a 'Accepted successfully to file:.*com.apple.chrono/timelines' /mnt/e/DSH-Fuxi/logs/carve-wall1/lscan.txt | sed -E 's/[0-9A-F]{8}-[0-9A-F-]{27}/#/g' | cut -c1-200 | sed -E 's#timelines/([^/]+)/.*#timelines/\1#' | sort | uniq -c | sort -rn | head -8
echo ---; grep -a 'Accepted successfully to file:.*com.apple.chrono/timelines' /mnt/e/DSH-Fuxi/logs/carve-auto200p/lscan.txt | sed -E 's/[0-9A-F]{8}-[0-9A-F-]{27}/#/g' | cut -c1-200 | sed -E 's#timelines/([^/]+)/.*#timelines/\1#' | sort | uniq -c | sort -rn | head -8